from pathlib import Path
from playwright.sync_api import sync_playwright
import os,json
r=Path(__file__).resolve().parents[1]
with sync_playwright() as pw:
 b=pw.webkit.launch(executable_path='/workspace/.cache/pw-mobile/run-webkit-local.sh',headless=True,env={**os.environ,'LIBGL_ALWAYS_SOFTWARE':'1','EGL_PLATFORM':'surfaceless'});p=b.new_page(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);errors=[];p.on('console',lambda m:errors.append(m.text) if m.type=='error' else None)
 p.add_init_script('''window.glTrace=[];{const ids=new WeakMap();let id=0;const label=o=>!o?null:ids.get(o)||(ids.set(o,++id),id);const orig=WebGL2RenderingContext.prototype.blitFramebuffer;WebGL2RenderingContext.prototype.blitFramebuffer=function(...args){if(window.glTrace.length<32){const read=this.getParameter(this.READ_FRAMEBUFFER_BINDING),draw=this.getParameter(this.DRAW_FRAMEBUFFER_BINDING);window.glTrace.push({args,read:label(read),draw:label(draw),readTexture:read?label(this.getFramebufferAttachmentParameter(this.READ_FRAMEBUFFER,this.COLOR_ATTACHMENT0,this.FRAMEBUFFER_ATTACHMENT_OBJECT_NAME)):null,drawTexture:draw?label(this.getFramebufferAttachmentParameter(this.DRAW_FRAMEBUFFER,this.COLOR_ATTACHMENT0,this.FRAMEBUFFER_ATTACHMENT_OBJECT_NAME)):null,modal:window.spiritState?.modal});}return orig.apply(this,args)}}''')
 p.goto('http://127.0.0.1:8770/',wait_until='networkidle');p.get_by_role('button',name='直接開始遊玩',exact=True).tap();p.wait_for_function('window.spiritReady&&window.spiritMobileTree?.tree?.id',timeout=120000);p.wait_for_timeout(1000);p.get_by_role('button',name='選擇這位夥伴',exact=True).nth(1).tap();p.wait_for_timeout(800);p.evaluate('window.spiritAction(JSON.stringify({kind:"menu",name:"close"}))');p.wait_for_timeout(1500)
 report=p.evaluate('({trace:window.glTrace,missing:window.spiritMobileMissingAssets||[],notice:document.getElementById("mobile-toast")?.textContent})');report['errors']=errors;(r/'validation/webkit-gl-probe.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps(report,ensure_ascii=False),flush=True);b.close()
